// ADR-831 (D-21 bis) — draft timesheet fixture for the timesheet lifecycle / compliance specs, prepared by the guarded
// recipe command (marked clone only). The specs used to rely on the DEV demo seeders (WorkforceTimesheetDemoSeeder),
// whose draft sheets are consumed by every run (submitted → locked) : the clone may hold none.
// The employee is created through the API by the spec (run ledger) ; here : one past week of completed time entries
// (the first day 06:00–19:00 = 12 h, a regulatory « daily maximum » finding) and the sheet generated by the REAL
// use case (draft). removeDraftTimesheet deletes exactly what was created, by employee and period.
import { recipePhp } from './recipe.js'

/** A past Monday → Sunday window (4 to 5 weeks ago), never overlapping the current week. */
export function pastWeek() {
  const d = new Date()
  d.setUTCDate(d.getUTCDate() - 28 - ((d.getUTCDay() + 6) % 7))
  const iso = x => x.toISOString().slice(0, 10)
  const start = iso(d)
  const end = new Date(d); end.setUTCDate(end.getUTCDate() + 6)

  return { start, end: iso(end), days: [0, 1, 2, 3, 4].map(i => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + i); return iso(x) }) }
}

export function prepareDraftTimesheet({ companyId, employeeId, week = pastWeek() }) {
  const entries = week.days.map((day, i) => {
    const [inT, outT, worked] = i === 0 ? ['06:00', '19:00', 720] : ['09:00', '17:00', 420]

    return `App\\Core\\Workforce\\TimeEntry::withoutGlobalScopes()->create(['company_id' => ${Number(companyId)}, 'employee_id' => ${Number(employeeId)}, 'date' => '${day}', 'clock_in' => '${day} ${inT}:00', 'clock_out' => '${day} ${outT}:00', 'status' => 'completed', 'total_worked_minutes' => ${worked}, 'total_break_minutes' => 60, 'source' => 'manual']);`
  }).join('\n')
  const out = recipePhp(`<?php
\\Illuminate\\Database\\Eloquent\\Model::unguard();
${entries}
$p = app(App\\Modules\\Workforce\\UseCases\\GenerateTimesheetUseCase::class)->execute(${Number(companyId)}, ${Number(employeeId)}, '${week.start}', '${week.end}');
echo 'RESULT='.$p->id.':'.$p->status;`)
  const m = out.match(/RESULT=(\d+):(\w+)/)
  if (!m || m[2] !== 'draft') throw new Error(`draft timesheet fixture failed: ${out}`)

  return { periodId: Number(m[1]), companyId: Number(companyId), employeeId: Number(employeeId), week }
}

export function removeDraftTimesheet(f) {
  if (!f) return
  recipePhp(`<?php
use Illuminate\\Support\\Facades\\DB;
$period = App\\Core\\Workforce\\TimesheetPeriod::withoutGlobalScopes()->where('company_id', ${f.companyId})->where('employee_id', ${f.employeeId})->whereKey(${f.periodId})->first();
if ($period) { DB::table('workforce_timesheet_lines')->where('timesheet_period_id', $period->id)->delete(); $period->delete(); }
$entries = App\\Core\\Workforce\\TimeEntry::withoutGlobalScopes()->where('company_id', ${f.companyId})->where('employee_id', ${f.employeeId})->whereBetween('date', ['${f.week.start}', '${f.week.end}'])->pluck('id');
DB::table('workforce_time_entry_breaks')->whereIn('time_entry_id', $entries)->delete();
App\\Core\\Workforce\\TimeEntry::withoutGlobalScopes()->whereIn('id', $entries)->delete();
echo 'ok';`)
}
